// app/Sources/GraphicFileSheetController.swift — File ▸ Rename Graphic…,
// Delete Graphic… and Restore Graphic Version… (spec §11 G-30; issue #103,
// issue batch B84): ONE small sheet for the three, a pop-up of the
// project's graphics over the three bodies in
// `ProjectDocument+GraphicFiles.swift` — the bodies `rename_graphic`,
// `delete_graphic` and `restore_graphic` call, so both doors refuse in the
// same sentences.
//
// **No second implementation.** Every act is one call of a body
// (`perform`); nothing here reaches a `GraphicStore` writer, an op or an
// undo registration, and no sentence a body throws is rewritten, prefixed
// or predicted: a refusal is shown word for word in `messageLabel` and the
// sheet stays up. The two guards written here name the CALL (spec §11
// D2-1): a new name that is empty or unchanged (`canConfirm`), and an item
// with nothing to list (`isOffered`).
//
// **`perform` runs from the button's action only**: each body ends in
// `rescan()`, which must never run from a `.graphicsDidChange` observer.
// Rename's `apply` is `performGroupedEdit`, never `applyEdit`: the clips'
// new name is one CLOSED undo step wherever the action was sent from, it
// does not throw, and the body's own re-read moves the file back when the
// edit was refused.

import AppKit

/// One of the three file acts a person can ask for.
enum GraphicFileAct: CaseIterable {
    case rename, delete, restore

    /// The File menu's title.
    var menuTitle: String {
        switch self {
        case .rename: return "Rename Graphic…"
        case .delete: return "Delete Graphic…"
        case .restore: return "Restore Graphic Version…"
        }
    }

    /// The sheet's title: the menu's without its "…".
    var sheetTitle: String { String(menuTitle.dropLast()) }

    var confirmTitle: String {
        switch self {
        case .rename: return "Rename"
        case .delete: return "Delete"
        case .restore: return "Restore"
        }
    }

    /// The sentence under the title (spec §11 G-30 (c), word for word).
    var hint: String {
        switch self {
        case .rename:
            return "Every clip that uses the graphic follows its new name, on the timeline and "
                + "inside nests. Undo renames it back when a clip uses it; a graphic no clip "
                + "uses is renamed back by renaming it again."
        case .delete:
            return "A graphic that clips still use cannot be deleted. Its code is kept with its "
                + "earlier versions, so Restore Graphic Version… brings it back. Deleting is "
                + "not an Undo step."
    case notNeeded
    /// Seeking, restoring, rebuilding, holding, or the start refused (a
    /// window plays): the clock runs again.
    case busy
}

/// The idle clock (spec §11 G-38 (b), (c)). Main only.
///
/// **Activity** restarts it and stops the running background pass at once:
/// every event in `activityEvents` the app receives (a local monitor, so
/// pointer motion alone and events in other apps do not count), every
/// `.projectDocumentDidChange` of any document (live ticks included), and
/// every `syncPrefetch` of any transport — play, pause, a rate change, a
/// seek — which also makes that transport `current`. An agent's call counts
/// only when it edits or moves a transport.
///
/// **At the delay** (read from the stored setting at every restart), with
/// the setting on and no transport playing, `current` is asked to start a
/// pass; a playing transport or `.busy` runs the clock again, `.notNeeded`
/// waits for the next activity. `current` is weak,
/// and an invalidated `Playback` has no item, so a late fire finds nothing.
final class BackgroundRender {
    static let shared = BackgroundRender()
    static let activityEvents: NSEvent.EventTypeMask = [
        .keyDown, .flagsChanged, .leftMouseDown, .leftMouseDragged, .rightMouseDown,
        .rightMouseDragged, .otherMouseDown, .otherMouseDragged, .scrollWheel, .magnify, .rotate,
        .swipe, .smartMagnify,
    ]

    private weak var current: Playback?
    /// Every transport that has moved: none may play when a pass starts.
    private let transports = NSHashTable<Playback>.weakObjects()
    private var timer: Timer?
    private var monitor: Any?
    private var observer: NSObjectProtocol?

    private init() {
        monitor = NSEvent.addLocalMonitorForEvents(matching: Self.activityEvents) {
            [weak self] event in
            self?.noteActivity(from: nil)
            return event
        }
        observer = NotificationCenter.default.addObserver(
            forName: .projectDocumentDidChange, object: nil, queue: nil
        ) { [weak self] _ in
            self?.noteActivity(from: nil)
        }
    }

    /// Activity: `playback`, when given, becomes `current`; the running pass
    /// stops; the one timer restarts at the stored delay.
    func noteActivity(from playback: Playback?) {
        if let playback {
            current = playback
            transports.add(playback)
        }
        GraphicPrefetch.shared.stopBackground()
        restartClock()
    }

    private func restartClock() {
        addArrangedSubview(settingsSectionHeader(headingLabel, info: infoButton))
        addArrangedSubview(delayRow)
    }

    // MARK: - Syncing

    /// The stored setting on the controls; the field and the stepper enabled
    /// only while the box is ticked, the field never written while it is
    /// being edited. Reads only, never writes.
    func sync() {
        let settings = BackgroundRenderSettings.load(from: defaults)
        backgroundBox.state = settings.enabled ? .on : .off
        delayField.isEnabled = settings.enabled
        delayStepper.isEnabled = settings.enabled
        delayStepper.integerValue = settings.delaySeconds
        if delayField.currentEditor() == nil {
            delayField.stringValue = String(settings.delaySeconds)
        }
    }

    // MARK: - Controls

    @objc func backgroundToggled(_ sender: Any?) {
        var settings = BackgroundRenderSettings.load(from: defaults)
        settings.enabled = backgroundBox.state == .on
        settings.save(to: defaults)
        sync()
    }

    /// The field's commit (Return or leaving it). Outside the range beeps and
    /// shows the stored value again, writing nothing.
    @objc func delayChanged(_ sender: Any?) {
        var settings = BackgroundRenderSettings.load(from: defaults)
        let typed = delayField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let seconds = Int(typed), BackgroundRenderSettings.delayRange.contains(seconds) else {
            NSSound.beep()
    static func explanation() -> String {
        [
            "While you leave Frame Job alone for the time set here, it draws the graphics "
                + "after the playhead in the window you last used, so they play smoothly from the "
                + "start. It stops as soon as you do anything in Frame Job and starts again after "
                + "the same wait, and it keeps the processor busy while it runs.",
            "The frames are held in memory, at most a quarter of this Mac's and less when memory "
                + "is short, until the window closes or newer frames replace them.",
        ].joined(separator: "\n\n")
    }
}
